        except ValueError:
            pass

        # D Mon YYYY (e.g. 3 Jan 2026)
        parts = d_str.split()
        if len(parts) == 3:
            day, mon, year = parts
            if mon in months and day.isdigit() and year.isdigit():
                try:
                    dt = datetime(int(year), months[mon], int(day))
                    return dt.strftime("%Y-%m-%d")
                except ValueError:
                    pass

        return None

