def max_load(events):
    if not events:
        return (0, 0)

    changes = {}
    for start, end, weight in events:
        changes[start] = changes.get(start, 0) + weight
        changes[end] = changes.get(end, 0) - weight

    max_l = 0
    best_t = 0
    curr_l = 0

    for t in sorted(changes.keys()):
        curr_l += changes[t]
        if curr_l > max_l:
            max_l = curr_l
            best_t = t

